<?php
namespace App\Http\Controllers\DeviceApi;use App\Http\Controllers\Controller;use App\Models\FirmwareDeploymentDevice;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class DeviceFirmwareController extends Controller { public function download(Request $request,string $target){$device=$request->attributes->get('device');$deploymentTarget=FirmwareDeploymentDevice::with('deployment.artifact')->where('device_id',$device->id)->findOrFail($target);$artifact=$deploymentTarget->deployment->artifact;abort_unless($artifact&&Storage::disk($artifact->storage_disk)->exists($artifact->storage_path),404);return Storage::disk($artifact->storage_disk)->download($artifact->storage_path,$artifact->original_filename,['Content-Type'=>$artifact->mime_type,'X-Content-SHA256'=>$artifact->sha256]);} }
